var e=JSON.parse(`[{"id":"RO-001","type":"RO","skill":"reading","difficulty":3,"timeLimit":180,"instructions":"将下方段落按正确顺序排列。","tags":["science","history"],"paragraphs":["This eventually led to the development of the modern computer as we know it today.","The first electronic computers were massive machines that filled entire rooms and consumed enormous amounts of power.","As technology advanced, components became smaller and more efficient, allowing computers to become increasingly compact and affordable.","The invention of the microprocessor in the early 1970s marked a major turning point in the history of computing."],"correctOrder":[1,3,2,0]},{"id":"RO-002","type":"RO","skill":"reading","difficulty":2,"timeLimit":180,"instructions":"将下方段落按正确顺序排列。","tags":["environment","society"],"paragraphs":["As a result, many cities have implemented recycling programs to reduce the amount of waste sent to landfills.","The increasing volume of waste produced by modern societies has become a significant environmental concern.","These programs have been largely successful, with recycling rates increasing steadily in many developed nations.","Landfills are rapidly reaching capacity, and the decomposition of waste produces harmful greenhouse gases."],"correctOrder":[1,3,0,2]},{"id":"RO-003","type":"RO","skill":"reading","difficulty":3,"timeLimit":180,"instructions":"将下方段落按正确顺序排列。","tags":["psychology","child development"],"paragraphs":["Around six months, most infants begin to produce repetitive syllables such as 'ba-ba' and 'da-da', a stage known as canonical babbling.","Language development in children follows a predictable sequence that begins at birth.","By their first birthday, many children produce their first recognizable words, signaling the transition to meaningful speech.","Even newborns show a preference for human voices and can distinguish between the sounds of different languages.","This babbling stage is essential for developing the motor control needed for articulate speech."],"correctOrder":[1,3,0,4,2]},{"id":"RO-004","type":"RO","skill":"reading","difficulty":2,"timeLimit":180,"instructions":"将下方段落按正确顺序排列。","tags":["business","entrepreneurship"],"paragraphs":["Once a viable concept is identified, developing a comprehensive business plan is the next essential step.","This plan should outline the target market, revenue model, and operational requirements in detail.","Starting a successful business begins with recognizing an unmet need or opportunity in the marketplace.","With a solid plan in place, entrepreneurs can then seek funding from investors or financial institutions to bring their vision to life."],"correctOrder":[2,0,1,3]},{"id":"RO-005","type":"RO","skill":"reading","difficulty":4,"timeLimit":180,"instructions":"将下方段落按正确顺序排列。","tags":["history","science"],"paragraphs":["Before this paradigm shift, the prevailing belief was that the Earth occupied the center of the universe.","Galileo's observations through his telescope provided crucial evidence supporting the Copernican model.","The Copernican Revolution fundamentally challenged humanity's understanding of its place in the cosmos.","Despite fierce opposition from religious authorities, the heliocentric view gradually gained acceptance among the scientific community.","Nicolaus Copernicus proposed that the Earth and other planets revolve around the Sun, rather than the Earth being the center."],"correctOrder":[2,0,4,1,3]},{"id":"RO-006","type":"RO","skill":"reading","difficulty":2,"timeLimit":180,"instructions":"将下方段落按正确顺序排列。","tags":["health","nutrition"],"paragraphs":["Understanding these basics can help individuals make informed choices about what they eat.","In contrast, complex carbohydrates found in whole grains provide sustained energy and are more nutritious.","Simple carbohydrates, such as those found in sugary snacks, cause rapid spikes in blood sugar levels.","Carbohydrates are one of the three main macronutrients that the human body requires for optimal function."],"correctOrder":[3,2,1,0]},{"id":"RO-007","type":"RO","skill":"reading","difficulty":3,"timeLimit":180,"instructions":"将下方段落按正确顺序排列。","tags":["technology","artificial intelligence"],"paragraphs":["Early AI systems were rule-based, relying on explicitly programmed instructions to perform specific tasks.","Modern machine learning techniques allow systems to improve their performance through exposure to data without explicit programming.","This evolution from rigid programming to flexible learning represents a fundamental shift in how machines can solve problems.","The field of artificial intelligence has evolved significantly since its inception in the mid-20th century.","These initial approaches, while useful for narrowly defined problems, proved incapable of handling the complexity of real-world situations."],"correctOrder":[3,0,4,1,2]},{"id":"RO-008","type":"RO","skill":"reading","difficulty":2,"timeLimit":180,"instructions":"将下方段落按正确顺序排列。","tags":["education","study skills"],"paragraphs":["One highly effective technique is spaced repetition, which involves reviewing material at gradually increasing intervals.","Students who employ active learning strategies tend to perform better on exams than those who rely on passive review.","This method takes advantage of the brain's natural forgetting curve to strengthen long-term memory retention.","Effective study habits can significantly improve academic performance and reduce the stress associated with exam preparation."],"correctOrder":[3,1,0,2]},{"id":"RO-009","type":"RO","skill":"reading","difficulty":4,"timeLimit":180,"instructions":"将下方段落按正确顺序排列。","tags":["philosophy","ethics"],"paragraphs":["Proponents argue that the potential benefits, such as eradicating genetic diseases, far outweigh the ethical concerns.","The development of gene editing technologies like CRISPR has opened up unprecedented possibilities for modifying human DNA.","Opponents, however, warn that this technology could lead to eugenics and exacerbate social inequalities.","This debate raises fundamental questions about the limits of human intervention in nature.","The scientific community remains divided on whether and under what circumstances human genetic modification should be permitted."],"correctOrder":[1,0,2,4,3]},{"id":"RO-010","type":"RO","skill":"reading","difficulty":2,"timeLimit":180,"instructions":"将下方段落按正确顺序排列。","tags":["environment","ocean"],"paragraphs":["When ocean water absorbs too much carbon dioxide, it undergoes a chemical reaction that reduces its pH level.","This process, known as ocean acidification, poses a serious threat to marine ecosystems worldwide.","Coral reefs are particularly vulnerable, as more acidic water makes it difficult for corals to build their calcium carbonate skeletons.","If current trends continue, many coral reef ecosystems could collapse within this century, with devastating consequences for marine biodiversity."],"correctOrder":[0,1,2,3]},{"id":"RO-011","type":"RO","skill":"reading","difficulty":3,"timeLimit":180,"instructions":"将下方段落按正确顺序排列。","tags":["economics","trade"],"paragraphs":["The Silk Road was not a single route but rather a vast network of trade paths connecting East Asia with the Mediterranean world.","Along these routes, merchants exchanged not only goods such as silk, spices, and precious metals but also ideas, religions, and technologies.","This extensive commercial network flourished from roughly the 2nd century BCE until the 15th century CE.","Its decline was hastened by the rise of maritime trade routes, which offered faster and safer transportation of goods between continents.","For over a millennium, the Silk Road served as the primary conduit for cultural and economic exchange between the East and West."],"correctOrder":[0,1,4,2,3]},{"id":"RO-012","type":"RO","skill":"reading","difficulty":2,"timeLimit":180,"instructions":"将下方段落按正确顺序排列。","tags":["science","weather"],"paragraphs":["These clouds form when warm, moist air rises and cools, causing water vapor to condense into visible droplets.","Thunderstorms typically develop in cumulonimbus clouds, which can extend to great heights in the atmosphere.","The rapid upward and downward movement of air within these clouds generates the electrical charges that produce lightning.","Thunder, which always accompanies lightning, is caused by the rapid expansion of air heated by the electrical discharge."],"correctOrder":[1,0,2,3]},{"id":"RO-013","type":"RO","skill":"reading","difficulty":3,"timeLimit":180,"instructions":"将下方段落按正确顺序排列。","tags":["literature","writing"],"paragraphs":["Authors must carefully balance these techniques to create narratives that feel both authentic and compelling to readers.","Foreshadowing plants subtle clues about future events, creating anticipation and encouraging readers to look for deeper connections.","Flashbacks, on the other hand, interrupt the chronological flow to provide essential background information about characters or situations.","Literary devices such as foreshadowing and flashback allow writers to manipulate narrative time for dramatic effect."],"correctOrder":[3,1,2,0]},{"id":"RO-014","type":"RO","skill":"reading","difficulty":4,"timeLimit":180,"instructions":"将下方段落按正确顺序排列。","tags":["politics","diplomacy"],"paragraphs":["The Congress of Vienna, convened in 1814 after the defeat of Napoleon, aimed to restore stability to a continent ravaged by decades of war.","This diplomatic gathering brought together representatives from all the major European powers of the era.","Its architects sought to create a balance of power that would prevent any single nation from dominating Europe again.","The resulting settlement established a framework for international relations that, despite its conservative nature, helped maintain relative peace for nearly a century.","While the Congress ultimately failed to address rising nationalist movements, its principles of multilateral diplomacy influenced international relations well into the 20th century."],"correctOrder":[0,1,2,3,4]},{"id":"RO-015","type":"RO","skill":"reading","difficulty":2,"timeLimit":180,"instructions":"将下方段落按正确顺序排列。","tags":["technology","communication"],"paragraphs":["The development of the telegraph in the 19th century was the first technology to separate communication from physical transportation.","This was followed by the telephone, which added the ability to transmit the human voice across vast distances in real time.","The internet represents the latest major revolution in communication, enabling instant transmission of text, images, and video globally.","Each of these innovations progressively reduced the barriers of time and distance that had historically limited human interaction."],"correctOrder":[0,1,3,2]},{"id":"RO-016","type":"RO","skill":"reading","difficulty":3,"timeLimit":180,"instructions":"将下方段落按正确顺序排列。","tags":["biology","evolution"],"paragraphs":["These variations meant that some individuals were better suited to their environment than others.","Darwin observed that there was considerable variation among individuals within any given species.","Over many generations, this process could lead to the emergence of entirely new species adapted to specific ecological niches.","He further noted that those with advantageous traits were more likely to survive, reproduce, and pass these traits on to their offspring.","This mechanism, which Darwin called natural selection, provides a compelling explanation for the diversity of life observed in nature."],"correctOrder":[1,0,3,4,2]},{"id":"RO-017","type":"RO","skill":"reading","difficulty":2,"timeLimit":180,"instructions":"将下方段落按正确顺序排列。","tags":["sports","psychology"],"paragraphs":["The pressure of competition can cause even highly skilled athletes to perform well below their capabilities.","Sport psychologists have identified several techniques that can help athletes manage performance anxiety effectively.","One commonly used approach involves deep breathing exercises and progressive muscle relaxation before competition.","With consistent practice, these mental skills can become as automatic as the physical skills developed through training."],"correctOrder":[0,1,2,3]},{"id":"RO-018","type":"RO","skill":"reading","difficulty":4,"timeLimit":180,"instructions":"将下方段落按正确顺序排列。","tags":["art","architecture"],"paragraphs":["Gothic architecture, which flourished in Europe during the High and Late Middle Ages, represented a dramatic departure from earlier Romanesque styles.","The development of pointed arches and flying buttresses allowed builders to construct taller structures with larger windows than ever before.","Stained glass windows, depicting biblical scenes and saints, served both an aesthetic and an educational purpose for a largely illiterate population.","These innovations transformed cathedrals from dark, fortress-like structures into soaring spaces filled with colored light.","The cathedral of Notre-Dame in Paris stands as one of the most celebrated examples of this architectural tradition."],"correctOrder":[0,1,3,2,4]},{"id":"RO-019","type":"RO","skill":"reading","difficulty":3,"timeLimit":180,"instructions":"将下方段落按正确顺序排列。","tags":["science","psychology"],"paragraphs":["This insight has important implications for how educators structure learning activities and assessments.","The spacing effect, first identified by Hermann Ebbinghaus in the 19th century, demonstrates that information is better retained when learning sessions are distributed over time.","In contrast, cramming or massed practice, although common among students, leads to rapid forgetting once the material is no longer actively studied.","Subsequent research has consistently confirmed that spaced practice produces more durable learning than massed practice across a wide range of subjects and age groups."],"correctOrder":[1,3,2,0]},{"id":"RO-020","type":"RO","skill":"reading","difficulty":3,"timeLimit":180,"instructions":"将下方段落按正确顺序排列。","tags":["business","marketing"],"paragraphs":["Modern marketing strategies increasingly rely on data analytics to understand consumer behavior and preferences.","This data-driven approach allows companies to deliver personalized advertisements and recommendations to individual consumers.","However, the collection and use of personal data has raised significant privacy concerns among consumers and regulators alike.","Balancing the benefits of targeted marketing with respect for individual privacy remains a key challenge for the industry.","Companies gather information from a variety of sources including online browsing habits, purchase history, and social media activity."],"correctOrder":[0,4,1,2,3]},{"id":"RO-021","type":"RO","skill":"reading","difficulty":2,"timeLimit":180,"instructions":"将下方段落按正确顺序排列。","tags":["health","exercise"],"paragraphs":["For those new to exercise, even moderate activities such as brisk walking can produce noticeable health improvements.","As fitness levels increase, individuals can gradually incorporate more intense activities such as running or strength training.","The key to sustaining an exercise routine is finding activities that are enjoyable and fit comfortably into one's daily schedule.","Regular physical activity is one of the most effective ways to improve both physical and mental wellbeing."],"correctOrder":[3,0,1,2]},{"id":"RO-022","type":"RO","skill":"reading","difficulty":3,"timeLimit":180,"instructions":"将下方段落按正确顺序排列。","tags":["history","civil rights"],"paragraphs":["His message of nonviolent resistance resonated with millions of Americans and drew international attention to the injustices of segregation.","Martin Luther King Jr. emerged as the most prominent leader of the American civil rights movement in the 1950s and 1960s.","This landmark legislation prohibited discrimination based on race, color, religion, sex, or national origin.","The movement's efforts culminated in the passage of the Civil Rights Act of 1964 and the Voting Rights Act of 1965.","Through organized protests, boycotts, and marches, King and his followers challenged the deeply entrenched system of racial segregation in the American South."],"correctOrder":[1,4,0,3,2]},{"id":"RO-023","type":"RO","skill":"reading","difficulty":4,"timeLimit":180,"instructions":"将下方段落按正确顺序排列。","tags":["science","neuroscience"],"paragraphs":["This discovery overturned the long-held belief that the adult brain was a fixed and unchanging organ.","Neuroplasticity refers to the brain's remarkable ability to reorganize itself by forming new neural connections throughout life.","This capacity for change underlies our ability to learn new skills, recover from brain injury, and adapt to new experiences.","Research has shown that even activities as simple as learning to juggle or playing a musical instrument can produce measurable changes in brain structure.","The implications of neuroplasticity extend to the treatment of conditions such as stroke, where targeted rehabilitation can help undamaged brain areas take over functions lost to injury."],"correctOrder":[1,0,2,3,4]},{"id":"RO-024","type":"RO","skill":"reading","difficulty":2,"timeLimit":180,"instructions":"将下方段落按正确顺序排列。","tags":["society","urban planning"],"paragraphs":["Green spaces within cities provide numerous benefits for both residents and the environment.","They also serve as important habitats for urban wildlife, supporting biodiversity within the built environment.","Parks and gardens offer places for recreation, relaxation, and social interaction, contributing to improved mental health.","For these reasons, many urban planners now prioritize the integration of green spaces into new development projects."],"correctOrder":[0,2,1,3]},{"id":"RO-025","type":"RO","skill":"reading","difficulty":3,"timeLimit":180,"instructions":"将下方段落按正确顺序排列。","tags":["media","journalism"],"paragraphs":["This process involves verifying information with multiple independent sources before publication.","Journalistic integrity depends on a commitment to factual accuracy and balanced reporting.","When errors do occur, responsible news organizations issue prompt corrections to maintain public trust.","Fact-checking is therefore one of the most fundamental practices in professional journalism.","Despite these standards, the pressure to publish quickly in the digital age has sometimes compromised the thoroughness of verification processes."],"correctOrder":[1,3,0,4,2]},{"id":"RO-026","type":"RO","skill":"reading","difficulty":3,"timeLimit":180,"instructions":"将下方段落按正确顺序排列。","tags":["science","genetics"],"paragraphs":["These instructions are encoded in the sequence of four chemical bases that make up the DNA molecule.","DNA, or deoxyribonucleic acid, serves as the hereditary material in almost all living organisms.","The specific order of these bases determines the genetic information available for building and maintaining an organism.","Each gene corresponds to a particular segment of DNA that provides instructions for producing a specific protein."],"correctOrder":[1,0,3,2]},{"id":"RO-027","type":"RO","skill":"reading","difficulty":2,"timeLimit":180,"instructions":"将下方段落按正确顺序排列。","tags":["travel","tourism"],"paragraphs":["Careful planning before departure can help travelers avoid common pitfalls and make the most of their experience.","With these preparations in place, visitors can focus on enjoying the unique attractions and cultural experiences their destination has to offer.","International travel requires preparation beyond simply booking flights and accommodation.","This includes researching visa requirements, obtaining necessary vaccinations, and familiarizing oneself with local customs and laws."],"correctOrder":[2,3,0,1]},{"id":"RO-028","type":"RO","skill":"reading","difficulty":4,"timeLimit":180,"instructions":"将下方段落按正确顺序排列。","tags":["history","war"],"paragraphs":["The assassination of Archduke Franz Ferdinand of Austria in June 1914 set off this chain of reactions among allied nations.","This unprecedented global conflict resulted in an estimated 20 million deaths and fundamentally reshaped the political map of Europe.","What began as a regional dispute quickly escalated as pre-existing alliance systems drew one nation after another into the fighting.","World War I, often called the Great War, was triggered by a complex web of alliances, militarism, and nationalism.","The war ended in 1918 with the defeat of the Central Powers and the signing of the Treaty of Versailles."],"correctOrder":[3,2,0,4,1]},{"id":"RO-029","type":"RO","skill":"reading","difficulty":2,"timeLimit":180,"instructions":"将下方段落按正确顺序排列。","tags":["food","cooking"],"paragraphs":["Once the water reaches a rolling boil, add the pasta and stir occasionally to prevent sticking.","Cooking pasta to the perfect texture requires attention to a few simple but important steps.","Finally, drain the pasta and toss it immediately with your chosen sauce while it is still hot.","First, bring a large pot of generously salted water to a boil over high heat.","Test the pasta for doneness about two minutes before the package instructions suggest, as it should be al dente."],"correctOrder":[1,3,0,4,2]},{"id":"RO-030","type":"RO","skill":"reading","difficulty":3,"timeLimit":180,"instructions":"将下方段落按正确顺序排列。","tags":["biology","ecology"],"paragraphs":["Bees and other pollinators are responsible for the reproduction of approximately 75 percent of the world's flowering plants.","The decline in global bee populations has therefore raised serious concerns among scientists and agricultural experts.","Without adequate pollination, crop yields would decrease dramatically, threatening global food supplies.","Factors contributing to this decline include pesticide use, habitat loss, and climate change."],"correctOrder":[0,1,3,2]},{"id":"RO-031","type":"RO","skill":"reading","difficulty":3,"timeLimit":180,"instructions":"将下方段落按正确顺序排列。","tags":["psychology","motivation"],"paragraphs":["Extrinsic motivation, on the other hand, comes from external rewards such as money, praise, or recognition.","Psychologists distinguish between two main types of motivation that drive human behavior.","Research suggests that while both forms can be effective, intrinsic motivation tends to produce more sustained engagement over the long term.","Intrinsic motivation arises from within the individual, driven by personal interest, enjoyment, or a sense of challenge."],"correctOrder":[1,3,0,2]},{"id":"RO-032","type":"RO","skill":"reading","difficulty":4,"timeLimit":180,"instructions":"将下方段落按正确顺序排列。","tags":["art","music"],"paragraphs":["This period produced composers such as Haydn, Mozart, and Beethoven, whose works remain central to the Western musical canon.","Classical music, in its narrowest sense, refers to the musical tradition that flourished in Europe between roughly 1750 and 1820.","Lasting approximately 70 years, it represented a shift toward clarity, balance, and formal structure in musical composition.","The Classical period is distinct from the broader term 'classical music', which encompasses centuries of Western art music from the medieval era to the present.","These composers established many of the musical forms still used today, including the symphony, sonata, and string quartet."],"correctOrder":[1,2,0,4,3]},{"id":"RO-033","type":"RO","skill":"reading","difficulty":2,"timeLimit":180,"instructions":"将下方段落按正确顺序排列。","tags":["technology","security"],"paragraphs":["Cybersecurity experts warn that individuals and organizations must remain vigilant against these evolving threats.","Common cyber threats include phishing attacks, ransomware, and data breaches that can compromise sensitive information.","Implementing strong passwords, regular software updates, and multi-factor authentication are basic protective measures everyone should adopt.","The increasing digitization of personal and professional data has made cybersecurity a critical concern for modern society."],"correctOrder":[3,1,2,0]},{"id":"RO-034","type":"RO","skill":"reading","difficulty":3,"timeLimit":180,"instructions":"将下方段落按正确顺序排列。","tags":["sociology","culture"],"paragraphs":["Social norms are the unwritten rules that govern behavior within a society or group.","Violating these norms can result in social sanctions ranging from mild disapproval to outright ostracism.","Individuals typically internalize these norms during childhood through the process of socialization.","Despite their invisible nature, social norms exercise a powerful influence over how people dress, speak, and interact with others.","These norms vary considerably across different cultures and historical periods, reflecting diverse values and traditions."],"correctOrder":[0,2,3,1,4]},{"id":"RO-035","type":"RO","skill":"reading","difficulty":2,"timeLimit":180,"instructions":"将下方段落按正确顺序排列。","tags":["health","sleep"],"paragraphs":["The blue light emitted by electronic devices can suppress melatonin production, making it more difficult to fall asleep.","Establishing a consistent bedtime routine helps signal to the body that it is time to wind down and prepare for rest.","Good sleep hygiene involves a set of practices that promote regular, restful sleep.","Additionally, avoiding caffeine in the afternoon and keeping the bedroom cool and dark can further improve sleep quality."],"correctOrder":[2,1,0,3]},{"id":"RO-036","type":"RO","skill":"reading","difficulty":4,"timeLimit":180,"instructions":"将下方段落按正确顺序排列。","tags":["philosophy","logic"],"paragraphs":["Inductive reasoning, by contrast, moves from specific observations to broader generalizations and theories.","While deductive arguments aim for certainty, inductive arguments can only provide probable conclusions at best.","Aristotle, the ancient Greek philosopher, was the first to develop a comprehensive system of deductive logic.","Formal logic distinguishes between deductive reasoning, which derives specific conclusions from general premises, and inductive reasoning.","A deductive argument is said to be valid if its conclusion necessarily follows from its premises, regardless of whether those premises are actually true."],"correctOrder":[2,3,4,0,1]},{"id":"RO-037","type":"RO","skill":"reading","difficulty":2,"timeLimit":180,"instructions":"将下方段落按正确顺序排列。","tags":["environment","energy"],"paragraphs":["Solar panels convert sunlight directly into electricity through the photovoltaic effect.","This makes solar energy one of the most promising sources of renewable power for the future.","Unlike fossil fuels, solar energy produces no direct greenhouse gas emissions during operation.","The cost of solar technology has decreased dramatically over the past decade, making it increasingly accessible to homeowners and businesses."],"correctOrder":[0,2,3,1]},{"id":"RO-038","type":"RO","skill":"reading","difficulty":3,"timeLimit":180,"instructions":"将下方段落按正确顺序排列。","tags":["education","literacy"],"paragraphs":["Phonics instruction, which teaches the relationship between letters and sounds, has been shown to be particularly effective for beginning readers.","Reading is a foundational skill that underpins success in virtually all other academic subjects.","The debate over the best methods for teaching reading has persisted for decades among educators and researchers.","Whole language approaches, in contrast, emphasize the importance of immersing children in rich literary environments and authentic texts.","Most experts now advocate for a balanced approach that incorporates elements of both methodologies."],"correctOrder":[1,2,0,3,4]},{"id":"RO-039","type":"RO","skill":"reading","difficulty":3,"timeLimit":180,"instructions":"将下方段落按正确顺序排列。","tags":["business","finance"],"paragraphs":["Compound interest occurs when the interest earned on an investment itself begins to earn interest.","The key to maximizing the benefits of compound interest is to start investing early and remain consistent over time.","Over long periods, the effects of compounding can dramatically increase the value of even modest initial investments.","Albert Einstein reportedly called compound interest the eighth wonder of the world, highlighting its remarkable power.","This exponential growth is why financial advisors emphasize the importance of long-term, disciplined investing."],"correctOrder":[0,2,3,4,1]},{"id":"RO-040","type":"RO","skill":"reading","difficulty":2,"timeLimit":180,"instructions":"将下方段落按正确顺序排列。","tags":["history","invention"],"paragraphs":["This innovation dramatically increased the speed and reduced the cost of producing printed materials.","Gutenberg's printing press, invented around 1440, is widely regarded as one of the most transformative inventions in human history.","The resulting spread of knowledge contributed to major historical movements including the Renaissance, the Reformation, and the Scientific Revolution.","For the first time, books and pamphlets could be produced in large quantities, making information accessible to a much broader segment of society."],"correctOrder":[1,0,3,2]},{"id":"RO-041","type":"RO","skill":"reading","difficulty":4,"timeLimit":180,"instructions":"将下方段落按正确顺序排列。","tags":["science","astronomy"],"paragraphs":["The universe began approximately 13.8 billion years ago in an event known as the Big Bang, when all matter and energy were concentrated in an infinitesimally small point.","As the universe expanded and cooled, these particles eventually combined to form atoms, predominantly hydrogen and helium.","This initial expansion was not an explosion in the conventional sense but rather a rapid stretching of space itself.","Gravity then pulled these atoms together into clouds that would eventually become stars and galaxies.","In the first moments after the Big Bang, the universe was an extremely hot and dense soup of elementary particles."],"correctOrder":[0,2,4,1,3]},{"id":"RO-042","type":"RO","skill":"reading","difficulty":2,"timeLimit":180,"instructions":"将下方段落按正确顺序排列。","tags":["sports","training"],"paragraphs":["Rest days are therefore not a sign of laziness but an essential component of any effective training program.","During intense exercise, muscle fibers experience microscopic tears that need time to repair and strengthen.","The body adapts and grows stronger during periods of rest, not during the workout itself.","Overtraining, characterized by persistent fatigue and declining performance, occurs when the balance between exercise and recovery is disrupted."],"correctOrder":[1,2,3,0]},{"id":"RO-043","type":"RO","skill":"reading","difficulty":3,"timeLimit":180,"instructions":"将下方段落按正确顺序排列。","tags":["media","journalism"],"paragraphs":["Citizen journalism, enabled by smartphones and social media, allows ordinary individuals to report on events as they unfold.","Traditional journalism involves professional reporters who adhere to established standards of verification and editorial oversight.","The relationship between these two forms of news gathering has both enriched and complicated the media landscape.","While citizen journalists can provide immediate, on-the-ground perspectives, they may lack the training to verify information or avoid bias.","Credible news organizations increasingly incorporate citizen-generated content while maintaining editorial standards through rigorous verification."],"correctOrder":[1,0,3,2,4]},{"id":"RO-044","type":"RO","skill":"reading","difficulty":3,"timeLimit":180,"instructions":"将下方段落按正确顺序排列。","tags":["science","chemistry"],"paragraphs":["Different elements are defined by the number of protons in their atoms, known as the atomic number.","An atom, the basic unit of matter, consists of a nucleus containing protons and neutrons, surrounded by orbiting electrons.","Protons carry a positive charge, electrons carry a negative charge, and neutrons carry no charge at all.","The periodic table organizes all known elements according to their atomic number and chemical properties in a systematic arrangement."],"correctOrder":[1,2,0,3]},{"id":"RO-045","type":"RO","skill":"reading","difficulty":4,"timeLimit":180,"instructions":"将下方段落按正确顺序排列。","tags":["politics","law"],"paragraphs":["This principle ensures that no one, regardless of their position or power, is exempt from the law.","The rule of law is a fundamental principle that holds all individuals, institutions, and the government itself accountable to publicly promulgated laws.","It stands in contrast to arbitrary rule, where decisions are made based on the whims of individuals rather than established legal standards.","Key elements of the rule of law include an independent judiciary, transparent legal processes, and the protection of fundamental rights.","Without the rule of law, societies risk descending into corruption, abuse of power, and the erosion of basic civil liberties."],"correctOrder":[1,0,2,3,4]},{"id":"RO-046","type":"RO","skill":"reading","difficulty":2,"timeLimit":180,"instructions":"将下方段落按正确顺序排列。","tags":["education","technology"],"paragraphs":["Digital tools in the classroom can enhance learning by providing interactive content and personalized instruction.","However, technology should complement, rather than replace, the guidance and expertise of a skilled teacher.","Educational technology has transformed the way students learn and teachers deliver instruction in recent years.","When used effectively, digital resources can help students develop critical thinking, collaboration, and problem-solving skills."],"correctOrder":[2,0,3,1]},{"id":"RO-047","type":"RO","skill":"reading","difficulty":3,"timeLimit":180,"instructions":"将下方段落按正确顺序排列。","tags":["psychology","relationships"],"paragraphs":["Active listening involves fully concentrating on what the speaker is saying rather than merely waiting for one's turn to respond.","Poor communication, on the other hand, is one of the most commonly cited reasons for relationship difficulties and breakdown.","Effective communication is consistently identified by researchers as one of the most important factors in maintaining healthy relationships.","This skill includes paying attention to nonverbal cues, asking clarifying questions, and reflecting back what has been heard to confirm understanding."],"correctOrder":[2,0,3,1]},{"id":"RO-048","type":"RO","skill":"reading","difficulty":2,"timeLimit":180,"instructions":"将下方段落按正确顺序排列。","tags":["nature","conservation"],"paragraphs":["Deforestation contributes significantly to climate change, as forests absorb vast amounts of carbon dioxide from the atmosphere.","The primary drivers of deforestation include agricultural expansion, logging for timber, and urban development.","When forests are cleared, not only is this carbon absorption capacity lost, but the stored carbon is also released back into the atmosphere.","Reforestation and sustainable forest management are critical strategies for mitigating the environmental impact of deforestation."],"correctOrder":[0,2,1,3]},{"id":"RO-049","type":"RO","skill":"reading","difficulty":4,"timeLimit":180,"instructions":"将下方段落按正确顺序排列。","tags":["literature","criticism"],"paragraphs":["New Criticism, which dominated mid-20th century literary studies, insisted that texts should be analyzed in isolation from their historical and biographical contexts.","This evolved into a wide range of interpretive approaches including feminist criticism, postcolonial theory, and reader-response criticism.","Literary theory provides the conceptual frameworks through which scholars interpret and evaluate literary works.","In the latter half of the 20th century, however, structuralism and post-structuralism challenged these assumptions.","Each of these approaches offers distinct insights while also reflecting the intellectual concerns and values of its time."],"correctOrder":[2,0,3,1,4]},{"id":"RO-050","type":"RO","skill":"reading","difficulty":3,"timeLimit":180,"instructions":"将下方段落按正确顺序排列。","tags":["health","disease"],"paragraphs":["Treatment with antibiotics revolutionized medicine in the 20th century, dramatically reducing deaths from bacterial infections.","However, overuse and misuse of antibiotics has accelerated the evolution of resistant bacteria strains.","Before antibiotics, even minor infections could become life-threatening, and surgical procedures carried extreme risks.","The World Health Organization has identified antibiotic resistance as one of the top ten global health threats facing humanity today."],"correctOrder":[2,0,1,3]},{"id":"RO-051","type":"RO","skill":"reading","difficulty":2,"timeLimit":180,"instructions":"将下方段落按正确顺序排列。","tags":["technology","robotics"],"paragraphs":["These machines can operate continuously without fatigue and with a level of precision that exceeds human capabilities.","Industrial robots have transformed manufacturing by automating repetitive and physically demanding tasks.","While concerns about job displacement are valid, robots have also created new employment opportunities in programming, maintenance, and system design.","The integration of artificial intelligence with robotics is further expanding the range of tasks that machines can perform autonomously."],"correctOrder":[1,0,2,3]},{"id":"RO-052","type":"RO","skill":"reading","difficulty":3,"timeLimit":180,"instructions":"将下方段落按正确顺序排列。","tags":["environment","biodiversity"],"paragraphs":["Coral reefs, often described as the rainforests of the sea, support approximately 25 percent of all marine species despite covering only 0.1 percent of the ocean floor.","Climate change compounds these threats by causing ocean warming and acidification, which lead to coral bleaching.","Protecting these vital ecosystems requires both local conservation measures and global action to address climate change.","These diverse ecosystems are threatened by overfishing, pollution, and coastal development worldwide."],"correctOrder":[0,3,1,2]},{"id":"RO-053","type":"RO","skill":"reading","difficulty":3,"timeLimit":180,"instructions":"将下方段落按正确顺序排列。","tags":["history","religion"],"paragraphs":["Religion has been a powerful force in shaping human societies, influencing everything from moral codes to political structures throughout recorded history.","The Protestant Reformation in the 16th century shattered the religious unity of Western Europe and triggered profound social and political changes.","Prior to the Reformation, the Catholic Church held near-absolute authority over religious matters across most of Europe.","Martin Luther's Ninety-five Theses, posted in 1517, challenged key Church doctrines and practices, particularly the sale of indulgences.","The resulting fragmentation of Christianity led to centuries of religious conflict but also contributed to the development of religious tolerance and pluralism."],"correctOrder":[0,2,3,1,4]},{"id":"RO-054","type":"RO","skill":"reading","difficulty":2,"timeLimit":180,"instructions":"将下方段落按正确顺序排列。","tags":["food","nutrition"],"paragraphs":["Proteins are essential macronutrients that serve as the building blocks for muscles, enzymes, and hormones.","While animal products such as meat, eggs, and dairy are complete protein sources, many plant foods can be combined to provide all necessary amino acids.","The human body requires 20 different amino acids, nine of which must be obtained through diet because the body cannot synthesize them.","Vegetarian and vegan diets can provide adequate protein when they include a variety of legumes, grains, nuts, and seeds."],"correctOrder":[0,2,1,3]},{"id":"RO-055","type":"RO","skill":"reading","difficulty":4,"timeLimit":180,"instructions":"将下方段落按正确顺序排列。","tags":["philosophy","consciousness"],"paragraphs":["Some philosophers and scientists argue that consciousness emerges from complex neural processes and can be fully explained in physical terms.","The hard problem of consciousness, a term coined by philosopher David Chalmers, refers to the question of why and how physical processes in the brain give rise to subjective experience.","Others maintain that consciousness represents a fundamental feature of the universe, irreducible to physical explanation.","These differing perspectives reflect deeper disagreements about the nature of reality and the limits of scientific inquiry.","This stands in contrast to what Chalmers calls the easy problems of consciousness, which concern the mechanisms underlying specific cognitive functions."],"correctOrder":[1,4,0,2,3]},{"id":"RO-056","type":"RO","skill":"reading","difficulty":3,"timeLimit":180,"instructions":"将下方段落按正确顺序排列。","tags":["business","innovation"],"paragraphs":["However, many innovative products fail because companies misjudge market demand or underestimate competing technologies.","Disruptive innovation refers to a process where a smaller company successfully challenges established businesses by entering at the bottom of the market.","These disruptors often target overlooked customer segments with more accessible or affordable offerings.","Over time, these innovations improve in quality and can displace established market leaders who failed to adapt."],"correctOrder":[1,2,3,0]},{"id":"RO-057","type":"RO","skill":"reading","difficulty":2,"timeLimit":180,"instructions":"将下方段落按正确顺序排列。","tags":["science","psychology"],"paragraphs":["Cognitive biases are systematic patterns of deviation from rational judgment that affect human decision-making.","Being aware of these biases can help individuals make more informed and objective decisions in both personal and professional contexts.","The confirmation bias, for example, leads people to favor information that confirms their existing beliefs while dismissing contradictory evidence.","Understanding these mental shortcuts can reduce errors in judgment and improve critical thinking."],"correctOrder":[0,2,1,3]},{"id":"RO-058","type":"RO","skill":"reading","difficulty":3,"timeLimit":180,"instructions":"将下方段落按正确顺序排列。","tags":["history","science"],"paragraphs":["Marie Curie was the first person to win Nobel Prizes in two different scientific fields.","Born in Warsaw in 1867, she moved to Paris to pursue her education at a time when women were largely excluded from higher education.","Her pioneering research on radioactivity laid the groundwork for significant advances in both physics and medicine.","Together with her husband Pierre Curie, she discovered the elements polonium and radium, achievements that earned her the Nobel Prize in Physics in 1903.","She later won the Nobel Prize in Chemistry in 1911 for her continued work on radium and its compounds."],"correctOrder":[1,3,4,0,2]},{"id":"RO-059","type":"RO","skill":"reading","difficulty":4,"timeLimit":180,"instructions":"将下方段落按正确顺序排列。","tags":["economics","globalization"],"paragraphs":["While globalization has lifted millions out of poverty through economic growth and trade, it has also exacerbated income inequality both within and between nations.","The rapid expansion of global trade and investment flows since the late 20th century has fundamentally transformed the world economy.","Critics argue that the benefits of globalization have disproportionately accrued to wealthy individuals and multinational corporations.","Globalization refers to the increasing interconnectedness of national economies through the movement of goods, services, capital, and labor across borders.","The debate over how to manage globalization to ensure its benefits are more broadly shared remains a central challenge for policymakers worldwide."],"correctOrder":[3,1,0,2,4]},{"id":"RO-060","type":"RO","skill":"reading","difficulty":2,"timeLimit":180,"instructions":"将下方段落按正确顺序排列。","tags":["health","wellness"],"paragraphs":["This mind-body practice combines physical postures, breathing exercises, and meditation to promote flexibility, strength, and relaxation.","Over time, consistent practice can lead to measurable improvements in both physical and psychological health.","Yoga originated in ancient India thousands of years ago as a spiritual and philosophical discipline.","Modern scientific studies have confirmed many of the health benefits that yoga practitioners have reported for centuries."],"correctOrder":[2,0,3,1]},{"id":"RO-061","type":"RO","skill":"reading","difficulty":3,"timeLimit":180,"instructions":"将下方段落按正确顺序排列。","tags":["technology","social media"],"paragraphs":["Social media algorithms are designed to maximize user engagement by showing content that elicits strong emotional responses.","While these platforms have connected billions of people globally, they have also been linked to increased rates of anxiety and depression among heavy users.","They have fundamentally changed how people form and maintain relationships, consume news, and construct their identities.","The constant exposure to curated, idealized representations of others' lives can lead to social comparison and feelings of inadequacy.","Social media platforms have become a ubiquitous presence in modern life, with billions of active users worldwide."],"correctOrder":[4,2,0,3,1]},{"id":"RO-062","type":"RO","skill":"reading","difficulty":2,"timeLimit":180,"instructions":"将下方段落按正确顺序排列。","tags":["education","memory"],"paragraphs":["Mnemonics are memory devices that help learners recall larger pieces of information through association with easily remembered patterns.","The method of loci, also known as the memory palace technique, involves associating items to be remembered with specific physical locations.","Acronyms, such as ROYGBIV for the colors of the rainbow, compress multiple items into a single pronounceable word.","These techniques are based on the principle that the human brain is better at remembering spatial, personal, and surprising information than abstract facts."],"correctOrder":[0,2,1,3]},{"id":"RO-063","type":"RO","skill":"reading","difficulty":3,"timeLimit":180,"instructions":"将下方段落按正确顺序排列。","tags":["politics","democracy"],"paragraphs":["A functioning democracy requires more than just free and fair elections at regular intervals.","When any of these elements is compromised, the quality and legitimacy of democratic governance suffer.","An independent judiciary ensures that laws are applied equally to all citizens and that government actions remain within constitutional limits.","It also depends on a free press that can investigate and report on government activities without fear of retaliation.","Civil society organizations provide channels for citizens to participate in public life between elections and hold leaders accountable."],"correctOrder":[0,3,2,4,1]},{"id":"RO-064","type":"RO","skill":"reading","difficulty":4,"timeLimit":180,"instructions":"将下方段落按正确顺序排列。","tags":["art","painting"],"paragraphs":["These artists discarded many of the conventions that had governed Western painting since the Renaissance, including linear perspective and realistic color.","Cubism, pioneered by Pablo Picasso and Georges Braque in the early 20th century, represented one of the most radical breaks with artistic tradition.","This approach fundamentally altered how artists conceived of pictorial space and influenced virtually every subsequent art movement.","Instead of depicting objects from a single fixed viewpoint, Cubist paintings presented multiple perspectives simultaneously, fragmenting forms into geometric shapes.","By challenging the assumption that art should faithfully reproduce visual reality, Cubism opened the door to pure abstraction."],"correctOrder":[1,0,3,2,4]},{"id":"RO-065","type":"RO","skill":"reading","difficulty":2,"timeLimit":180,"instructions":"将下方段落按正确顺序排列。","tags":["environment","resource management"],"paragraphs":["Water scarcity affects more than 40 percent of the global population, a figure that is expected to rise due to climate change and population growth.","Agriculture accounts for approximately 70 percent of global freshwater withdrawals, making it the largest consumer of water resources.","Improving irrigation efficiency and adopting water-conserving farming techniques are therefore essential strategies for addressing water scarcity.","Desalination technology offers another potential solution, though it remains energy-intensive and expensive for many regions."],"correctOrder":[0,1,2,3]},{"id":"RO-066","type":"RO","skill":"reading","difficulty":3,"timeLimit":180,"instructions":"将下方段落按正确顺序排列。","tags":["science","geology"],"paragraphs":["The outermost layer, the crust, is a thin shell of solid rock that varies in thickness from about 5 to 70 kilometers.","The Earth's interior is composed of several distinct layers, each with its own physical and chemical properties.","Below the mantle, the outer core is a liquid layer composed primarily of iron and nickel, and its movement generates Earth's magnetic field.","Beneath the crust lies the mantle, a thick layer of hot, slowly flowing rock that extends to a depth of about 2,900 kilometers.","At the very center, the inner core is a solid sphere of iron and nickel alloy, despite temperatures exceeding 5,000 degrees Celsius."],"correctOrder":[1,0,3,2,4]},{"id":"RO-067","type":"RO","skill":"reading","difficulty":2,"timeLimit":180,"instructions":"将下方段落按正确顺序排列。","tags":["psychology","emotion"],"paragraphs":["This capacity enables individuals to navigate social situations more effectively and build stronger interpersonal connections.","Emotional intelligence encompasses the ability to recognize, understand, and manage one's own emotions as well as the emotions of others.","Research suggests that emotional intelligence may be an even stronger predictor of career success than traditional measures of cognitive ability.","Unlike IQ, which remains relatively stable throughout life, emotional intelligence can be developed and improved through deliberate practice and training."],"correctOrder":[1,0,2,3]},{"id":"RO-068","type":"RO","skill":"reading","difficulty":3,"timeLimit":180,"instructions":"将下方段落按正确顺序排列。","tags":["history","exploration"],"paragraphs":["His expedition, which departed from Spain in 1519, was the first to circumnavigate the Earth, though Magellan himself did not survive the entire journey.","Despite these challenges, the voyage provided conclusive evidence that the Earth was round and that the oceans were interconnected.","Ferdinand Magellan, a Portuguese explorer sailing under the Spanish flag, set out to find a western sea route to the Spice Islands in the early 16th century.","The journey was fraught with hardship, including starvation, scurvy, and violent conflicts with indigenous peoples.","Only one of the five original ships and 18 of the approximately 270 original crew members completed the historic three-year voyage."],"correctOrder":[2,0,3,4,1]},{"id":"RO-069","type":"RO","skill":"reading","difficulty":4,"timeLimit":180,"instructions":"将下方段落按正确顺序排列。","tags":["law","human rights"],"paragraphs":["The Universal Declaration of Human Rights, adopted by the United Nations General Assembly in 1948, established the first internationally recognized articulation of fundamental human rights.","Eleanor Roosevelt, who chaired the drafting committee, played a pivotal role in shepherding the document through a complex international negotiation process.","The declaration's 30 articles cover civil, political, economic, social, and cultural rights, including the right to life, liberty, education, and freedom of expression.","Drafted in the aftermath of World War II and the Holocaust, the declaration represented a collective determination to prevent such atrocities from occurring again.","Although not legally binding, the declaration has inspired numerous binding international treaties and has been incorporated into many national constitutions."],"correctOrder":[0,3,1,2,4]},{"id":"RO-070","type":"RO","skill":"reading","difficulty":2,"timeLimit":180,"instructions":"将下方段落按正确顺序排列。","tags":["science","oceanography"],"paragraphs":["Tides are the periodic rise and fall of sea levels caused by the gravitational forces exerted by the Moon and the Sun on Earth's oceans.","The Moon's gravitational pull is the primary driver of tides, although the Sun also exerts a significant influence.","When the Sun and Moon align, their gravitational forces combine to produce especially high spring tides.","These daily tidal cycles play a crucial role in shaping coastal ecosystems and have been harnessed to generate renewable tidal energy."],"correctOrder":[0,1,2,3]},{"id":"RO-071","type":"RO","skill":"reading","difficulty":3,"timeLimit":180,"instructions":"将下方段落按正确顺序排列。","tags":["business","entrepreneurship"],"paragraphs":["A minimum viable product allows entrepreneurs to test their assumptions with real users before committing substantial resources.","The lean startup methodology emphasizes rapid experimentation and customer feedback over elaborate business planning.","This iterative approach reduces the risk of building products that nobody wants and helps startups adapt quickly to market feedback.","Successful entrepreneurs learn to pivot when data suggests their original concept is not working as expected."],"correctOrder":[1,0,2,3]},{"id":"RO-072","type":"RO","skill":"reading","difficulty":2,"timeLimit":180,"instructions":"将下方段落按正确顺序排列。","tags":["health","disease prevention"],"paragraphs":["Vaccination has been one of the most successful public health interventions in history, saving millions of lives each year.","Diseases that once killed or disabled millions, such as smallpox and polio, have been eliminated or dramatically reduced through widespread immunization.","Herd immunity occurs when a sufficiently high proportion of a population is vaccinated, making the spread of disease from person to person unlikely.","Despite overwhelming scientific evidence supporting vaccine safety, misinformation and distrust have led to declining vaccination rates in some communities."],"correctOrder":[0,1,2,3]},{"id":"RO-073","type":"RO","skill":"reading","difficulty":3,"timeLimit":180,"instructions":"将下方段落按正确顺序排列。","tags":["literature","poetry"],"paragraphs":["Free verse, which does not adhere to regular meter or rhyme, emerged as the dominant form of poetic expression in the 20th century.","Earlier poetic traditions, such as the sonnet or the villanelle, imposed strict structural constraints including specific line counts and rhyme schemes.","Poetry has evolved significantly over the centuries, reflecting changes in aesthetic sensibilities and cultural values.","This shift reflected broader modernist impulses to break from convention and find new ways of representing human experience in language."],"correctOrder":[2,1,0,3]},{"id":"RO-074","type":"RO","skill":"reading","difficulty":4,"timeLimit":180,"instructions":"将下方段落按正确顺序排列。","tags":["science","climate"],"paragraphs":["Earth's climate has undergone dramatic shifts throughout its 4.5 billion year history, ranging from complete global glaciation to warm periods with no polar ice.","However, the current rate of warming is at least ten times faster than anything seen in the geological record.","These past climate changes, driven by factors such as volcanic activity, variations in Earth's orbit, and shifts in ocean circulation, typically occurred over tens of thousands or even millions of years.","This unprecedented pace leaves ecosystems and human societies with far less time to adapt than during previous climate transitions.","The geological record thus both illuminates the mechanisms of climate change and underscores the extraordinary nature of the current crisis."],"correctOrder":[0,2,1,3,4]},{"id":"RO-075","type":"RO","skill":"reading","difficulty":2,"timeLimit":180,"instructions":"将下方段落按正确顺序排列。","tags":["technology","data"],"paragraphs":["Big data refers to the massive volumes of structured and unstructured data generated by digital technologies every day.","Organizations across industries are increasingly using big data analytics to identify patterns, predict trends, and make more informed business decisions.","However, the sheer volume of data presents challenges in terms of storage, processing, and analysis that require specialized tools and expertise.","The growth of big data has been fueled by the proliferation of smartphones, social media platforms, and internet-connected devices."],"correctOrder":[0,3,1,2]},{"id":"RO-076","type":"RO","skill":"reading","difficulty":3,"timeLimit":180,"instructions":"将下方段落按正确顺序排列。","tags":["sociology","urban studies"],"paragraphs":["Gentrification occurs when previously working-class urban neighborhoods experience an influx of more affluent residents and investment.","These changes can lead to improved services and reduced crime rates, benefiting both new and existing residents.","This process often begins when lower housing costs attract artists, students, and other risk-tolerant residents to a neighborhood.","However, rising property values frequently displace long-term residents who can no longer afford to live in the transformed neighborhood."],"correctOrder":[0,2,1,3]},{"id":"RO-077","type":"RO","skill":"reading","difficulty":2,"timeLimit":180,"instructions":"将下方段落按正确顺序排列。","tags":["education","career"],"paragraphs":["Internships provide students and recent graduates with valuable hands-on experience in their chosen fields.","This practical knowledge often proves as important as academic qualifications when employers evaluate candidates.","Through internships, individuals can apply theoretical knowledge learned in classrooms to real-world professional situations.","Many interns also develop professional networks that can lead to full-time employment opportunities after graduation."],"correctOrder":[0,2,1,3]},{"id":"RO-078","type":"RO","skill":"reading","difficulty":4,"timeLimit":180,"instructions":"将下方段落按正确顺序排列。","tags":["philosophy","metaphysics"],"paragraphs":["Plato's Theory of Forms posits that the physical world we perceive through our senses is merely a shadow of a higher, more fundamental reality.","For Plato, each physical object is an imperfect copy of its corresponding Form, just as a circle drawn on paper can never perfectly match the abstract mathematical concept of a circle.","According to this view, true knowledge is not obtained through sensory experience but through rational contemplation of these eternal and unchanging Forms.","The most famous expression of this idea appears in Plato's Allegory of the Cave, where prisoners mistake shadows on a wall for reality itself.","This metaphysical framework has influenced Western philosophy for more than two millennia, shaping debates about the nature of reality, knowledge, and the relationship between mind and world."],"correctOrder":[0,1,3,2,4]},{"id":"RO-079","type":"RO","skill":"reading","difficulty":3,"timeLimit":180,"instructions":"将下方段落按正确顺序排列。","tags":["environment","pollution"],"paragraphs":["Exposure to poor air quality has been linked to respiratory diseases, cardiovascular problems, and premature death.","Air pollution, caused by vehicle emissions, industrial activity, and the burning of fossil fuels, represents one of the most significant environmental health risks worldwide.","The World Health Organization estimates that air pollution contributes to approximately seven million deaths globally each year.","Governments have implemented measures such as emission standards, congestion pricing, and investment in public transportation to combat this problem."],"correctOrder":[1,0,2,3]},{"id":"RO-080","type":"RO","skill":"reading","difficulty":2,"timeLimit":180,"instructions":"将下方段落按正确顺序排列。","tags":["psychology","development"],"paragraphs":["Erik Erikson proposed that human development occurs in eight distinct stages from infancy to old age, each characterized by a specific psychosocial crisis.","How individuals resolve these crises shapes their personality development and influences their ability to navigate subsequent stages.","For example, the first stage in Erikson's model involves the crisis of trust versus mistrust, which infants face during their earliest months.","Successful resolution of this stage provides the foundation for forming healthy relationships throughout the rest of life."],"correctOrder":[0,1,2,3]},{"id":"RO-081","type":"RO","skill":"reading","difficulty":3,"timeLimit":180,"instructions":"将下方段落按正确顺序排列。","tags":["technology","blockchain"],"paragraphs":["Blockchain technology enables the creation of decentralized digital ledgers that record transactions across a network of computers.","This innovation eliminates the need for a central authority to validate transactions, reducing costs and potentially increasing security.","Once recorded in a block and added to the chain, data becomes effectively immutable, as altering any single block would require changing all subsequent blocks.","While originally developed for the cryptocurrency Bitcoin, blockchain technology has potential applications in areas ranging from supply chain management to voting systems."],"correctOrder":[0,1,2,3]},{"id":"RO-082","type":"RO","skill":"reading","difficulty":2,"timeLimit":180,"instructions":"将下方段落按正确顺序排列。","tags":["art","cinema"],"paragraphs":["The development of sound technology in the late 1920s fundamentally transformed the motion picture industry.","Filmmakers quickly adapted to the new medium, incorporating dialogue, music, and sound effects to enhance storytelling.","Before the introduction of synchronized sound, movies were accompanied by live musicians and occasionally by title cards for dialogue.","Some silent film stars, however, found their careers ended because their voices did not match audience expectations built on their visual personas."],"correctOrder":[0,2,1,3]},{"id":"RO-083","type":"RO","skill":"reading","difficulty":4,"timeLimit":180,"instructions":"将下方段落按正确顺序排列。","tags":["history","scientific revolution"],"paragraphs":["Francis Bacon championed the empirical method, arguing that knowledge should be derived from systematic observation and experimentation rather than from ancient authorities.","Before the Scientific Revolution, natural philosophy was largely based on the teachings of Aristotle and other classical thinkers, which had been accepted for centuries.","The Scientific Revolution of the 16th and 17th centuries marked the emergence of modern science as a distinct approach to understanding the natural world.","This emphasis on empirical evidence, direct observation, and mathematical description laid the epistemological foundations for all subsequent scientific inquiry.","Galileo Galilei further advanced this approach by insisting that natural phenomena should be described mathematically and verified through controlled experiments."],"correctOrder":[2,1,0,4,3]},{"id":"RO-084","type":"RO","skill":"reading","difficulty":2,"timeLimit":180,"instructions":"将下方段落按正确顺序排列。","tags":["health","aging"],"paragraphs":["The global population is aging at an unprecedented rate, driven by declining fertility rates and increasing life expectancy.","This demographic shift presents both challenges and opportunities for healthcare systems, pension programs, and the broader economy.","Older adults remain active contributors to society, providing volunteer services, caregiving for family members, and continuing to work past traditional retirement age.","Policymakers must adapt social support systems to accommodate this new demographic reality while recognizing the continued contributions of older citizens."],"correctOrder":[0,1,2,3]},{"id":"RO-085","type":"RO","skill":"reading","difficulty":3,"timeLimit":180,"instructions":"将下方段落按正确顺序排列。","tags":["science","physics"],"paragraphs":["Einstein's theory of special relativity, published in 1905, established that the speed of light in a vacuum is constant regardless of the observer's motion.","One of the most counterintuitive implications of this theory is time dilation, where time passes more slowly for objects moving at speeds approaching the speed of light.","General relativity, published a decade later, extended these ideas to include gravity, reimagining it as a curvature of spacetime caused by mass and energy.","These theories replaced Newtonian mechanics, which had been the foundation of physics for over two centuries, and have been confirmed by numerous experiments."],"correctOrder":[0,1,2,3]},{"id":"RO-086","type":"RO","skill":"reading","difficulty":3,"timeLimit":180,"instructions":"将下方段落按正确顺序排列。","tags":["business","customer service"],"paragraphs":["Customer experience has become a key competitive differentiator as products and services increasingly become commoditized.","Companies that excel at customer experience typically invest in employee training, data analytics, and user-friendly digital interfaces.","A single negative experience can cause a customer to switch to a competitor, and disgruntled customers often share their complaints widely on social media.","This is why organizations increasingly measure customer satisfaction metrics such as Net Promoter Score and prioritize rapid issue resolution."],"correctOrder":[0,2,3,1]},{"id":"RO-087","type":"RO","skill":"reading","difficulty":2,"timeLimit":180,"instructions":"将下方段落按正确顺序排列。","tags":["environment","wildlife"],"paragraphs":["Migration is one of the most remarkable phenomena in the animal kingdom, with some species traveling thousands of kilometers each year.","These journeys are triggered by seasonal changes in temperature, food availability, or breeding requirements.","For instance, the Arctic tern undertakes the longest migration of any animal, traveling from its Arctic breeding grounds to the Antarctic and back each year.","Scientists use tracking technologies such as GPS tags and satellite imagery to study migration patterns and understand the challenges these animals face."],"correctOrder":[0,1,2,3]},{"id":"RO-088","type":"RO","skill":"reading","difficulty":4,"timeLimit":180,"instructions":"将下方段落按正确顺序排列。","tags":["literature","world literature"],"paragraphs":["Haruki Murakami's novels blend elements of Western popular culture with distinctly Japanese sensibilities, creating a literary universe that feels simultaneously familiar and surreal.","Japanese literature has a rich and varied tradition spanning more than a thousand years, from the eleventh-century masterpiece The Tale of Genji to contemporary works that grapple with the complexities of modern life.","This international appeal has made Murakami one of the most widely read Japanese authors of all time, with his works translated into more than 50 languages.","In the postwar period, authors such as Yukio Mishima and Kenzaburo Oe explored themes of national identity, tradition, and the trauma of war.","Murakami's characters often navigate parallel realities, confront the unexplained, and search for meaning in a world where traditional social structures have dissolved."],"correctOrder":[1,3,0,4,2]},{"id":"RO-089","type":"RO","skill":"reading","difficulty":2,"timeLimit":180,"instructions":"将下方段落按正确顺序排列。","tags":["health","mental health"],"paragraphs":["With the right treatment and support, most people with depression can achieve significant improvement in their symptoms.","Depression is a common but serious mood disorder that affects how a person feels, thinks, and handles daily activities.","Treatment options include psychotherapy, medication such as antidepressants, and lifestyle modifications.","Symptoms must persist for at least two weeks for a diagnosis, and can include persistent sadness, loss of interest in activities, changes in appetite, and difficulty concentrating."],"correctOrder":[1,3,2,0]},{"id":"RO-090","type":"RO","skill":"reading","difficulty":3,"timeLimit":180,"instructions":"将下方段落按正确顺序排列。","tags":["history","empire"],"paragraphs":["Its network of roads, aqueducts, and administrative centers integrated diverse regions from Britain to North Africa and from Spain to the Middle East.","At its height in the 2nd century CE, the Roman Empire controlled territory spanning three continents and governed an estimated 70 million people.","Latin, the language of Rome, evolved into the Romance languages and remained the language of scholarship and diplomacy in Europe for over a thousand years.","Even after the Western Empire's fall in 476 CE, Roman law, architecture, and political concepts continued to shape European civilization for centuries to come.","The empire's enduring legacy can be seen in modern legal systems, architectural styles, and the widespread use of Romance languages."],"correctOrder":[1,0,2,3,4]},{"id":"RO-091","type":"RO","skill":"reading","difficulty":3,"timeLimit":180,"instructions":"将下方段落按正确顺序排列。","tags":["science","climate science"],"paragraphs":["Climate models are sophisticated computer programs that simulate the interactions of the atmosphere, oceans, land surface, and ice.","However, all models involve some degree of uncertainty because of the inherent complexity of the climate system.","These models are tested by comparing their outputs against historical climate data, a process known as hindcasting.","Scientists use these models to project how the climate might change under different scenarios of future greenhouse gas emissions."],"correctOrder":[0,2,3,1]},{"id":"RO-092","type":"RO","skill":"reading","difficulty":2,"timeLimit":180,"instructions":"将下方段落按正确顺序排列。","tags":["technology","privacy"],"paragraphs":["Individuals generate vast amounts of data through everyday activities such as browsing the internet, using social media, and shopping online.","In response, privacy regulations such as the General Data Protection Regulation have been implemented to give individuals more control over their personal information.","This data, when aggregated and analyzed, can reveal detailed profiles of individual behavior, preferences, and even health conditions.","Digital privacy has emerged as one of the most pressing concerns of the information age, as the collection of personal data has become ubiquitous."],"correctOrder":[3,0,2,1]},{"id":"RO-093","type":"RO","skill":"reading","difficulty":4,"timeLimit":180,"instructions":"将下方段落按正确顺序排列。","tags":["philosophy","political theory"],"paragraphs":["Direct democracy, as practiced in ancient Athens, allowed citizens to vote directly on legislation rather than through elected representatives.","Debates about the ideal form of democracy have persisted since its emergence in ancient Greece two and a half millennia ago.","In an ideal deliberative democracy, citizens would engage in reasoned discussion, consider diverse perspectives, and arrive at decisions through a process of mutual persuasion.","This ancient model, however, was limited to a relatively small citizen body that excluded women, slaves, and foreigners.","Modern representative democracy, developed during the Enlightenment, addressed the practical challenge of governing large populations but introduced the possibility that representatives might not faithfully reflect the will of their constituents."],"correctOrder":[1,0,3,4,2]},{"id":"RO-094","type":"RO","skill":"reading","difficulty":3,"timeLimit":180,"instructions":"将下方段落按正确顺序排列。","tags":["media","film"],"paragraphs":["Documentary films aim to present factual information about real events, people, and issues in a compelling narrative format.","The genre encompasses a wide range of approaches, from observational documentaries that minimize the filmmaker's presence to participatory works where the director actively engages with subjects.","Unlike fictional films, documentaries raise distinct ethical questions about representation, consent, and the filmmaker's responsibility to both subjects and audiences.","Modern documentary filmmakers employ diverse techniques including interviews, archival footage, animation, and dramatic reenactments to tell their stories."],"correctOrder":[0,2,1,3]},{"id":"RO-095","type":"RO","skill":"reading","difficulty":2,"timeLimit":180,"instructions":"将下方段落按正确顺序排列。","tags":["health","fitness"],"paragraphs":["Stretching increases blood flow to muscles and improves the range of motion around joints, reducing the risk of injury.","Hence, a balanced fitness routine should include both dynamic warm-up stretches before exercise and static stretches for cool-down afterward.","A proper warm-up prepares the cardiovascular system for the increased demands of exercise and gradually elevates heart rate.","While often overlooked, warm-up and stretching routines are essential components of safe and effective exercise."],"correctOrder":[3,2,0,1]},{"id":"RO-096","type":"RO","skill":"reading","difficulty":3,"timeLimit":180,"instructions":"将下方段落按正确顺序排列。","tags":["education","pedagogy"],"paragraphs":["In a flipped classroom, students are introduced to new content at home through video lectures or readings, and then apply their learning through problem-solving activities during class time.","Traditional classroom instruction typically involves the teacher delivering content through lectures during class, with students completing homework independently afterward.","This model allows teachers to provide more individualized support during the application phase, when students are most likely to need assistance.","The flipped classroom model inverts this sequence by moving content delivery outside of class and bringing active learning into the classroom."],"correctOrder":[1,0,3,2]},{"id":"RO-097","type":"RO","skill":"reading","difficulty":4,"timeLimit":180,"instructions":"将下方段落按正确顺序排列。","tags":["science","medicine"],"paragraphs":["The discovery of the double helix structure of DNA by James Watson and Francis Crick in 1953 was built upon crucial X-ray crystallography data produced by Rosalind Franklin.","This elegant solution to the puzzle of genetic replication opened entirely new fields of biological inquiry.","Before this breakthrough, scientists understood that genes carried hereditary information but did not know the physical structure that enabled genetic material to be copied accurately.","The double helix model revealed how genetic information could be stored in the sequence of base pairs and faithfully replicated during cell division.","Six decades later, the Human Genome Project completed the mapping of all 3 billion base pairs in human DNA, a feat made possible by the foundational insights of Watson, Crick, and Franklin."],"correctOrder":[2,0,3,1,4]},{"id":"RO-098","type":"RO","skill":"reading","difficulty":2,"timeLimit":180,"instructions":"将下方段落按正确顺序排列。","tags":["society","volunteering"],"paragraphs":["These experiences can build character, develop empathy, and provide practical skills that are valuable in both personal and professional contexts.","Volunteering benefits not only the recipients of service but also the volunteers themselves.","Studies have shown that regular volunteers report higher levels of life satisfaction and lower rates of depression compared to non-volunteers.","Many organizations actively seek volunteers to support their missions, making it relatively easy for individuals to find meaningful opportunities."],"correctOrder":[1,2,0,3]},{"id":"RO-099","type":"RO","skill":"reading","difficulty":3,"timeLimit":180,"instructions":"将下方段落按正确顺序排列。","tags":["history","technology"],"paragraphs":["The Space Race, a 20th-century competition between the United States and the Soviet Union, drove extraordinary technological progress.","The Apollo program, culminating in the 1969 moon landing, represented perhaps the greatest technological achievement in human history.","This intense rivalry produced innovations that extended far beyond space exploration, including advances in computing, materials science, and satellite communications.","It began in 1957 when the Soviet Union launched Sputnik, the first artificial satellite to orbit the Earth.","The global positioning system, weather forecasting satellites, and many everyday technologies can trace their origins to this period of intense space competition."],"correctOrder":[0,3,1,2,4]},{"id":"RO-100","type":"RO","skill":"reading","difficulty":2,"timeLimit":180,"instructions":"将下方段落按正确顺序排列。","tags":["psychology","wellbeing"],"paragraphs":["Practicing gratitude, where individuals consciously acknowledge the positive aspects of their lives, has been linked to increased happiness and reduced stress.","Positive psychology, a relatively recent branch of the field, focuses on the factors that contribute to human flourishing rather than solely on treating mental illness.","Researchers in this field have identified several practices that can enhance wellbeing, including gratitude exercises, mindfulness, and cultivating strong social relationships.","Regular gratitude journaling, where people write down things they are thankful for several times per week, has been shown to produce lasting improvements in mood and life satisfaction."],"correctOrder":[1,2,0,3]}]`);export{e as default};